INSERT INTO sys_api (title,path,method,api_group,created_at,updated_at,created_by) SELECT '查看迁移计划','/api/system/upgrade/migration-plan','GET','服务升级',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 WHERE NOT EXISTS (SELECT 1 FROM sys_api WHERE path='/api/system/upgrade/migration-plan' AND method='GET');
INSERT INTO sys_menu_api (menu_id,api_id) SELECT m.id,a.id FROM sys_menu m JOIN sys_api a ON a.path='/api/system/upgrade/migration-plan' AND a.method='GET' WHERE m.permission='system:upgrade:read' AND NOT EXISTS (SELECT 1 FROM sys_menu_api ma WHERE ma.menu_id=m.id AND ma.api_id=a.id);
INSERT INTO sys_casbin_rule (ptype,v0,v1,v2,v3,v4,v5) SELECT 'p','role_1','/api/system/upgrade/migration-plan','GET','*','','' WHERE NOT EXISTS (SELECT 1 FROM sys_casbin_rule WHERE ptype='p' AND v0='role_1' AND v1='/api/system/upgrade/migration-plan' AND v2='GET');
